export function quantity(task){return Math.round(task.scans.reduce((n,s)=>n+s.qty,0)*1e6)/1e6;}
export function daysLeft(expiry){return expiry?Math.round((Date.parse(expiry+'T00:00:00Z')-Date.parse(DAY+'T00:00:00Z'))/86400000):null;}
const now=()=>new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',hour12:false});
export function notify(state,type,title,body,links={}){const n={id:'n'+Date.now()+Math.random().toString(16).slice(2),type,title,body,read:!state.settings.alerts,time:now(),...links};state.notices.unshift(n);return n;}
export function log(state,title,body,type='update'){state.events.unshift({title,body,type,time:now()});}
function error(state,t,message){notify(state,'error','검수 확인이 필요해요',message,{taskId:t.id});return {ok:false,message};}
export function scan(state,taskId,code){const t=state.tasks.find(x=>x.id===taskId);if(!t)return {ok:false,message:'작업을 찾을 수 없습니다.'};if(t.state==='done'||t.allocated)return {ok:false,message:'일괄 등록한 내역에는 추가 스캔할 수 없습니다.'};const selected=state.stocks.find(x=>x.id===t.stockId),label=resolveLabel(state,t,code);
 if(!label)return error(state,t,'등록되지 않은 바코드입니다. 라벨·수량 기준에서 시연 라벨을 확인하세요.');const item=label.stock;
 if(item.kind!==t.kind||item.item!==selected.item)return error(state,t,'지시 품목과 다른 품목입니다. 보관함에 추가하지 않았습니다.');if(item.id!==selected.id)return error(state,t,'지시 LOT와 다른 LOT입니다. LOT 선택을 먼저 확인하세요.');
 if(t.direction==='out'&&(state.holds||[]).includes(item.lot))return error(state,t,'품질 확인으로 출고 보류 중인 LOT입니다. 품질 담당자 확인이 필요합니다.');
 if(t.direction==='out'&&daysLeft(item.expiry)!==null&&daysLeft(item.expiry)<0)return error(state,t,'소비기한이 지난 LOT입니다. 출고할 수 없습니다.');
 if(label.needsWeight)return error(state,t,'원자재 상품코드에는 중량이 없습니다. 실측 중량(kg)을 먼저 입력하세요.');
 if(!Number.isFinite(label.qty)||label.qty<=0||Math.round(label.qty*1e6)!==label.qty*1e6)return error(state,t,'양수 수량을 소수 6자리 이내로 입력해 주세요.');
 const canonical=label.mode==='package'?'PK-'+item.id+'-'+String(label.serial).padStart(4,'0'):label.code;
 if(label.unique&&t.scans.some(x=>x.code===canonical))return error(state,t,'이미 스캔한 포장입니다. 다른 포장 라벨을 스캔하세요.');
 if(label.unique&&state.tasks.some(other=>other.id!==t.id&&other.direction===t.direction&&other.allocated&&other.scans.some(x=>x.code===canonical)))return error(state,t,'다른 작업에서 이미 등록한 고유 포장입니다.');
 const next=Math.round((quantity(t)+label.qty)*1e6)/1e6;if(next>t.qty)return error(state,t,'지시 수량을 초과했습니다. 추가 스캔을 차단했습니다.');if(t.direction==='out'&&next>item.stock)return error(state,t,'선택한 창고·LOT의 가용 재고가 부족합니다.');t.scans.push({code:canonical,qty:label.qty,mode:label.mode,unique:label.unique});t.state='progress';return {ok:true,message:`${item.name} · +${label.qty} ${item.unit} / 스캔 보관함에 추가`};}
export function scanMany(state,taskId,codes){const results=codes.map(code=>({code,...scan(state,taskId,code)}));return {accepted:results.filter(x=>x.ok).length,rejected:results.filter(x=>!x.ok).length,results};}
export function undo(state,id){const t=state.tasks.find(x=>x.id===id);if(t&&!t.allocated&&t.state!=='done'){t.scans.pop();t.state=t.scans.length?'progress':'waiting';return true;}return false;}
export function saveAllocation(state,id){const t=state.tasks.find(x=>x.id===id);if(!t||t.state==='done')return {ok:false,message:'이미 완료된 작업입니다.'};if(t.allocated)return {ok:true,message:'이미 저장된 내역입니다.'};if(quantity(t)!==t.qty)return {ok:false,message:'지시 수량을 모두 검수해 주세요.'};const s=state.stocks.find(x=>x.id===t.stockId);if(t.direction==='out'&&(state.holds||[]).includes(s.lot))return error(state,t,'품질 보류 LOT는 등록할 수 없습니다.');if(t.direction==='out'&&s.stock<t.qty)return error(state,t,'재고가 변경되었습니다. 가용 재고를 다시 확인해 주세요.');if(t.direction==='out'&&t.kind==='P'){s.stock-=t.qty;log(state,'차량·LOT 일괄 등록',`${t.scans.length}개 스캔 / ${t.vehicle} / ${s.lot} / 재고 −${t.qty} ${s.unit}`,'stock');stockWarning(state,s,t);}else{log(state,'입출고 내역 일괄 등록',`${t.scans.length}개 스캔 / ${t.id} / ${s.lot} / ${t.qty} ${s.unit} / 확정 대기`);}t.allocated=true;t.state='saved';return {ok:true,message:t.kind==='P'&&t.direction==='out'?'차량·LOT 내역 저장 및 재고 차감 완료':'검수 내역이 등록되었습니다. 확정해 주세요.'};}
function stockWarning(state,s,t){if(s.stock<s.threshold)notify(state,'stock','기준 재고보다 적어요',`${s.name} · ${s.stock} ${s.unit} / 시연 기준 ${s.threshold} ${s.unit}`,{stockId:s.id,taskId:t.id});}
export function confirm(state,id){const t=state.tasks.find(x=>x.id===id);if(!t)return {ok:false,message:'작업을 찾을 수 없습니다.'};if(t.state==='done')return {ok:false,message:'이미 ERP에 반영된 작업입니다.'};if(!t.allocated)return {ok:false,message:'검수 내역을 먼저 저장해 주세요.'};if(t.direction==='in'&&!t.quality)return {ok:false,message:'입고 품질 확인을 완료해 주세요.'};const s=state.stocks.find(x=>x.id===t.stockId),before=s.stock;if(t.direction==='out'&&(state.holds||[]).includes(s.lot))return error(state,t,'품질 보류 LOT는 확정할 수 없습니다.');if(t.direction==='out'&&t.kind!=='P'){if(s.stock<t.qty)return error(state,t,'재고가 부족하여 확정할 수 없습니다.');s.stock-=t.qty;stockWarning(state,s,t);}if(t.direction==='in')s.stock+=t.qty;t.state='done';t.completedAt=now();log(state,t.direction==='in'?'입고 확정 · 재고 증가':t.kind==='P'?'출고 확정 · 단가 기록':'출고 확정 · 재고 차감',`${t.id} / ${s.lot} / ${t.kind==='P'&&t.direction==='out'?'저장 시 차감 완료 · 추가 차감 없음':`${before} → ${s.stock} ${s.unit}`}`,'complete');notify(state,'complete',t.direction==='in'?'입고 결과가 ERP에 반영됐어요':'출고 결과가 ERP에 반영됐어요',`${s.name} ${t.qty} ${s.unit} · ${t.id}`,{taskId:t.id});state.history.unshift({id:t.id,title:t.title,kind:t.kind,direction:t.direction,qty:t.qty,unit:s.unit,lot:s.lot,time:t.completedAt});return {ok:true,message:'ERP 반영이 완료되었습니다.'};}
export function changeLot(state,id,stockId){const t=state.tasks.find(x=>x.id===id),s=state.stocks.find(x=>x.id===stockId),old=state.stocks.find(x=>x.id===t?.stockId);if(!t||!s||!old||t.allocated||t.state==='done'||old.item!==s.item||old.kind!==s.kind)return false;t.stockId=s.id;t.scans=[];t.state='waiting';return true;}
